#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int *first = malloc(sizeof *first);
    if (first == NULL) {
        return 1;
    }
    int *second = malloc(sizeof *second);
    if (second == NULL) {
        free(first);
        return 1;
    }
    *first = 12;
    *second = 18;
    printf("Sum: %d\n", *first + *second);
    free(second);
    free(first);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int sum(const int *values, size_t count)
{
    int total = 0;
    for (size_t i = 0; i < count; i++) {
        total += values[i];
    }
    return total;
}

int main(void)
{
    int *owner = malloc(3 * sizeof *owner);
    if (owner == NULL) {
        return 1;
    }
    owner[0] = 4;
    owner[1] = 7;
    owner[2] = 9;
    const int *view = owner;
    printf("Borrowed sum: %d\n", sum(view, 3));
    free(owner);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int total = 0;
    for (int round = 1; round <= 3; round++) {
        int *value = malloc(sizeof *value);
        if (value == NULL) {
            return 1;
        }
        *value = round * 10;
        total += *value;
        free(value);
    }
    printf("Total: %d\n", total);
    return 0;
}

